import{_ as l,a0 as p,w as u,s as c,I as o,x as e,a1 as r,A as a,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const X=JSON.parse('{"title":"教你在 Ubuntu 上使用 LXC 容器 | LCTT x X-CMD","titleTemplate":false,"description":"教你在 Ubuntu 上使用 LXC 容器 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"教你在 Ubuntu 上使用 LXC 容器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"教你在 Ubuntu 上使用 LXC 容器 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141029 How to create and manage LXC containers on Ubuntu","title":"教你在 Ubuntu 上使用 LXC 容器","tag":"201411","desc":""},"relativePath":"201411/20141029 How to create and manage LXC containers on Ubuntu.md","filePath":"[post].md"}'),i={name:"201411/20141029 How to create and manage LXC containers on Ubuntu.md"};function d(m,t,b,x,C,L){const n=p("Link");return u(),c("div",null,[t[18]||(t[18]=o("h1",{id:"教你在-ubuntu-上使用-lxc-容器",tabindex:"-1"},[e("教你在 Ubuntu 上使用 LXC 容器 "),o("a",{class:"header-anchor",href:"#教你在-ubuntu-上使用-lxc-容器","aria-label":"Permalink to “教你在 Ubuntu 上使用 LXC 容器”"},"​")],-1)),o("p",null,[t[2]||(t[2]=e("使用“容器”來保證主機環境的安全性，這個概念早在十年前就已經存在（例如 FreeBSD 的 jail 虛擬化技術），但是直到最近，隨着部署雲架構需求越來越多，像 LXC 和 ",-1)),r(n,{href:"http://xmodulo.com/docker-containers-centos-fedora.html"},{default:a(()=>[...t[0]||(t[0]=[e("Docker",-1)])]),_:1}),t[3]||(t[3]=e(" 這種 Linux 下的容器才成為被關注的焦點。當然，由於主流廠商（雲服務商如亞馬遜主推 AWS，微軟主推 Azure；發行版如紅帽、Ubuntu等）組成的強大靠山，",-1)),r(n,{href:"http://xmodulo.com/manage-linux-containers-docker-ubuntu.html"},{default:a(()=>[...t[1]||(t[1]=[e("Docker",-1)])]),_:1}),t[4]||(t[4]=e(" 已經被放在媒體的聚光燈下面，其實，Docker 裏面所謂的“容器”技術是由 LXC 提供的。",-1))]),t[19]||(t[19]=s(`<p>你只是一個普通的 Linux 用户，那 Docker/LXC 能為你帶來什麼好處呢？容器可以將你的應用在不同的 Linux 發行版之間遷移。想像一下這個場景：你正在用的發行版是 Debian，你喜歡它的穩定性，同時你又想玩一款最新的 Ubuntu 遊戲，你不需要在電腦上裝雙系統然後重啓進入 Ubuntu，也不需要在 Debian 上跑一個耗資源的 Ubuntu 虛擬機，你只需要簡單地生成一個 Ubuntu 容器就夠了。</p><p>拋開 Docker 的好處不談，讓我們聊一下 LXC 容器的好處：我可以使用 libvirt 提供的接口來管理 LXC，這些接口和 Docker 沒有任何關係。如果你有使用基於 libvirt 庫的管理工具（例如 virt-manager 和 virsh），你就可以使用它們來管理 LXC 容器。</p><p>在這篇教程中，我只介紹標準 LXC 容器管理工具的命令列操作，來教你<strong>如何在 Ubuntu 下創建和管理 LXC 容器</strong>。</p><h3 id="ubuntu-下安裝-lxc" tabindex="-1">Ubuntu 下安裝 LXC <a class="header-anchor" href="#ubuntu-下安裝-lxc" aria-label="Permalink to “Ubuntu 下安裝 LXC”">​</a></h3><p>使用下面的命令安裝 LXC 在用户態的工具：</p><pre><code>$ sudo apt-get install lxc
</code></pre><p>然後檢查當前內核是否支持 LXC。如果所有結果都是“enable”，説明內核支持：</p><pre><code>$ lxc-checkconfig 
</code></pre><p><img src="https://farm4.staticflickr.com/3955/15655792445_d462957ee9_z.jpg" alt=""></p><p>安裝完 LXC 工具後，就能看到 LXC 自動創建了一塊橋接網卡（lxcbr0，可以在 /etc/lxc/default.conf 中設置）。</p><p><img src="https://farm6.staticflickr.com/5598/15035046834_a53c092230_z.jpg" alt=""></p><p>當你創建了 LXC 容器後，它的網口會自動鏈接到這個橋接網卡上，然後這個容器就能和外部世界通信了。</p><h3 id="創建-lxc-容器" tabindex="-1">創建 LXC 容器 <a class="header-anchor" href="#創建-lxc-容器" aria-label="Permalink to “創建 LXC 容器”">​</a></h3><p>為了在指定環境下（比如 Debian Wheezy 64位）創建 LXC 容器，你需要一個相應的 LXC 模板。幸運的是 LXC 提供的工具集成了一整套現成的 LXC 模板，你可以在 /usr/share/lxc/templates 目錄下找到它們。</p><pre><code> $ ls /usr/share/lxc/templates 
</code></pre><p><img src="https://farm4.staticflickr.com/3954/15035046824_d15d1cbf6e_z.jpg" alt=""></p><p>一個 LXC 模板實質上就是一個腳本，用於創建指定環境下的容器。當你創建 LXC 容器時，你需要用到它們。</p><p>比如你要新建 Ubuntu 容器，使用下面的命令即可：</p><pre><code>$ sudo lxc-create -n &lt;container-name&gt; -t ubuntu 
</code></pre><p><img src="https://farm8.staticflickr.com/7559/15035638763_07d63e23ef_z.jpg" alt=""></p><p>默認情況下，這個命令會創建一個最小的 Ubuntu 環境，版本號與你的宿主機一致，我這邊是“活潑的蠑螈”（版本號是13.10），64位。</p><p>當然你也可以創建任何你喜歡的版本，只要在命令裏面加一個版本參數即可。舉個例子，創建 Ubuntu 14.10 的容器：</p><pre><code>$ sudo lxc-create -n &lt;container-name&gt; -t ubuntu -- --release utopic 
</code></pre><p>這個命令就會下載安裝指定環境下的軟件包，創建新容器。整個過程需要幾分鐘時間，與容器的類型有關，所以，你可能需要耐心等待。</p><p><img src="https://farm4.staticflickr.com/3933/15469152369_6a48943cf3_z.jpg" alt=""></p><p>下載安裝完所有軟件包後，LXC 容器鏡像就創建完成了，你可以看到默認的登錄界面。容器被放到 /var/lib/lxc/&lt;容器名&gt; 這個目錄下，容器的根文件系統放在 /var/lib/lxc/&lt;容器名&gt;/rootfs 目錄下。</p><p>創建過程中下載的軟件包保存在 /var/cache/lxc 目錄下面，當你想另外建一個一樣的容器時，可以省去很多下載時間。</p><p>用下面的命令看看主機上所有的 LXC 容器：</p><pre><code>$ sudo lxc-ls --fancy 
</code></pre><hr><pre><code>NAME  STATE    IPV4  IPV6  AUTOSTART  
------------------------------------
test-lxc   STOPPED  -     -     NO         
</code></pre><p>使用下面的命令啓動容器。參數“-d”將容器作為後台進程打開。如果沒有指定這個參數，你可以在控制台界面上直接把容器的運行程序關閉（LCTT譯註：Ctrl+C組合鍵）。</p><pre><code>$ sudo lxc-start -n &lt;container-name&gt; -d 
</code></pre><p>打開容器後，看看狀態：</p><pre><code>$ sudo lxc-ls --fancy 
</code></pre><hr><pre><code>NAME  STATE    IPV4       IPV6  AUTOSTART  
-----------------------------------------
lxc   RUNNING  10.0.3.55  -     NO         
</code></pre><p>容器狀態是“運行中”，容器 IP 是10.0.3.55。</p><p>你也可以看到容器的網絡接口（比如我這裏是 vethJ06SFL）自動與 LXC 內部網橋（lxcbr0）連上了：</p><pre><code>$ brctl show lxcbr0 
</code></pre><p><img src="https://farm4.staticflickr.com/3932/15656618342_53c4bc19ca_z.jpg" alt=""></p><h3 id="管理-lxc-容器" tabindex="-1">管理 LXC 容器 <a class="header-anchor" href="#管理-lxc-容器" aria-label="Permalink to “管理 LXC 容器”">​</a></h3><p>我們已經學習了怎麼創建和啓動 LXC 容器，現在來看看怎麼玩一個正在運行着的容器。</p><p>第一步：打開容器控制台：</p><pre><code>$ sudo lxc-console -n &lt;container-name&gt; 
</code></pre><p><img src="https://farm8.staticflickr.com/7538/15470225050_d093cb1028_z.jpg" alt=""></p><p>使用“Crtl+a q”組合鍵退出控制台。</p><p>停止、刪除容器：</p><pre><code>$ sudo lxc-stop -n &lt;container-name&gt;
$ sudo lxc-destroy -n &lt;container-name&gt; 
</code></pre><p>複製容器，用下面的命令：</p><pre><code>$ sudo lxc-stop -n &lt;container-name&gt;
$ sudo lxc-clone -o &lt;container-name&gt; -n &lt;new-container-name&gt;
</code></pre><h3 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to “常見問題”">​</a></h3><p>這個小節主要介紹你們在使用 LXC 過程中碰到過的問題。</p><ol><li><p>創建 LXC 容器時遇到下面的錯誤：</p><p>$ sudo lxc-create -n test-lxc -t ubuntu</p></li></ol><hr><pre><code>lxc-create: symbol lookup error: /usr/lib/x86_64-linux-gnu/liblxc.so.1: undefined symbol: cgmanager_get_pid_cgroup_abs_sync
</code></pre><p>錯誤的原因是你運行了最新的 LXC，但是它所依賴的 libcgmanager 版本較老，兩者不兼容。升級下 libcmanager 即可解決問題：</p><pre><code>$ sudo apt-get install libcgmanager0 
</code></pre><hr>`,59)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),r(n,{href:"http://xmodulo.com/lxc-containers-ubuntu.html"},{default:a(()=>[...t[5]||(t[5]=[e("http://xmodulo.com/lxc-containers-ubuntu.html",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),r(n,{href:"http://xmodulo.com/author/nanni"},{default:a(()=>[...t[7]||(t[7]=[e("Dan Nanni",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),r(n,{href:"https://github.com/bazz2"},{default:a(()=>[...t[8]||(t[8]=[e("bazz2",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創翻譯，",-1)),r(n,{href:"http://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const T=l(i,[["render",d]]);export{X as __pageData,T as default};
